    mstore_method_id = [["mstore", buf, util.abi_method_id(abi_signature)]]
    if len(args) == 0:
        encode_args = ["pass"]
    else:
        encode_args = abi_encode(buf + 32, args_as_tuple, context, bufsz=buflen)
    return buf, mstore_method_id + [encode_args], args_ofst, args_len
