class PIDAutotune(object):
    def __init__(self, setpoint, out_step=10, sampletime=5, lookback=60,
                 out_min=float('-inf'), out_max=float('inf'), noiseband=0.5, time=time):
        if setpoint is None:
            raise ValueError('setpoint must be specified')
        if out_step < 1:
            raise ValueError('out_step ({}) must be greater or equal to 1'.format(out_step))
        if sampletime < 1:
            raise ValueError('sampletime ({}) must be greater or equal to 1'.format(sampletime))
        if lookback < sampletime:
            raise ValueError('lookback ({lb}) must be greater or equal to sampletime ({st})'.format(lb=lookback, st=sampletime))
        if out_min >= out_max:
            raise ValueError('out_min ({omn}) must be less than out_max ({omx})'.format(omn=out_min, omx=out_max))
        self._time = time
        self._logger = logging.getLogger(__name__)
        self._inputs = deque(maxlen=round(lookback / sampletime))
        self._sampletime = sampletime * 1000
        self._setpoint = setpoint
        self._outputstep = out_step
        self._noiseband = noiseband
        self._out_min = out_min
        self._out_max = out_max
        self._state = PIDAutotune.STATE_OFF
        self._peak_timestamps = deque(maxlen=5)
        self._peaks = deque(maxlen=5)
        self._output = 0
        self._last_run_timestamp = 0
        self._peak_type = 0
        self._peak_count = 0
        self._initial_output = 0
        self._induced_amplitude = 0
        self._Ku = 0
        self._Pu = 0
        self._total_cycles = 0
        self._logger.info("PID Autotune started")
            abs_max = self._peaks[-2]
