                room_id,
                requester.user,
                medium,
                address,
                id_server,
                requester,
                txn_id=None,
            )
        result = {"room_id": room_id}
        if room_alias:
            result["room_alias"] = room_alias.to_string()
            yield directory_handler.send_room_alias_update_event(
