        fn = fn.replace("\\", "/").split("/")[-1]
    if fn.lower() in bad:
        fn = "_" + fn
    if ANYWIN:
        remap = [
            ["<", "＜"],
            [">", "＞"],
            [":", "："],
            ['"', "＂"],
            ["/", "／"],
            ["\\", "＼"],
            ["|", "｜"],
            ["?", "？"],
            ["*", "＊"],
        ]
        for a, b in [x for x in remap if x[0] not in ok]:
            fn = fn.replace(a, b)
        bad = ["con", "prn", "aux", "nul"]
        for n in range(1, 10):
