    rc: int,
    cmd: Union[list[bytes], list[str]],
    serr: str,
    logger: Optional["NamedLogger"] = None,
    color: Union[int, str] = 0,
    verbose: bool = False,
) -> None:
    if rc < 0:
        rc = 128 - rc
    if not rc or rc < 126 and not verbose:
        return
    s = None
    if rc > 128:
        try:
            s = str(signal.Signals(rc - 128))
        except:
            pass
    elif rc == 126:
        s = "invalid program"
    elif rc == 127:
        s = "program not found"
    elif verbose:
        s = "unknown"
    else:
        s = "invalid retcode"
    if s:
        t = "{} <{}>".format(rc, s)
    else:
        t = str(rc)
    try:
        c = " ".join([fsdec(x) for x in cmd])
    except:
        c = str(cmd)
    t = "error {} from [{}]".format(t, c)
    if serr:
        t += "\n" + serr
    if logger:
        logger(t, color)
    else:
        raise Exception(t)
