            if forwarded_proto == "http":
                forwarded_port = "80"
            if forwarded_proto == "https":
                forwarded_port = "443"
    if forwarded_host:
        if ":" in forwarded_host and forwarded_host[-1] != "]":
            host, port = forwarded_host.rsplit(":", 1)
