            failed = True
            if is_quoted(value):
                failed = False
                value = unescape(value[1:-1].lstrip("\\/"))
            elif is_token(value):
                failed = False
            elif parts:
                _value = f"{value};{parts[0]}"
                if is_quoted(_value):
                    parts.pop(0)
