def log_request_and_response_for_debugging(
    prepared_request: PreparedRequest, response: Response
) -> None:
    """Log SaaS request and response in dev mode only"""
    if CONFIG.dev_mode:
        logger.info(
            "\n\n-----------SAAS REQUEST-----------"
            "\n{} {}"
            "\nheaders: {}"
            "\nbody: {}"
            "\nresponse: {}",
