                return {"message": "No config was given."}, 400
            try:
                config = json.loads(config)
            except json.JSONDecodeError as e:
                app.logger.debug(e, exc_info=True)
                return {"message": "Given config is invalid JSON."}, 400
            try:
                current_config.set(config)
