    def _get_content_type(self, file, body, id, content_type=None):
        headers = getattr(file, 'headers', None)
        if headers and 'content-type' in headers:
            content_type = headers['content-type']
        else:
            if not isinstance(body, bytes):
                body = body.data
            content_type, enc = guess_content_type(
                getattr(file, 'filename', id), body, content_type)
        return content_type
    def _read_data(self, file):
        import transaction
        n = 1 << 16
        if isinstance(file, str):
            raise ValueError("Must be bytes")
        if isinstance(file, bytes):
            size = len(file)
            if size < n:
                return (file, size)
            file = BytesIO(file)
        if isinstance(file, FileUpload) and not file:
            raise ValueError('File not specified')
        if hasattr(file, '__class__') and file.__class__ is Pdata:
            size = len(file)
            return (file, size)
        seek = file.seek
        read = file.read
        seek(0, 2)
        size = end = file.tell()
        if size <= 2 * n:
            seek(0)
            if size < n:
                return read(size), size
            return Pdata(read(size)), size
        transaction.savepoint(optimistic=True)
        if self._p_jar is None:
            seek(0)
            return Pdata(read(size)), size
        _next = None
        while end > 0:
            pos = end - n
            if pos < n:
                pos = 0
            seek(pos)
            data = Pdata(read(end - pos))
            self._p_jar.add(data)
            data.next = _next
            transaction.savepoint(optimistic=True)
            data._p_deactivate()
            assert data._p_oid is not None
            assert data._p_state == -1
            _next = data
            end = pos
        return (_next, size)
    def PUT(self, REQUEST, RESPONSE):
        """Handle HTTP PUT requests"""
        self.dav__init(REQUEST, RESPONSE)
        self.dav__simpleifhandler(REQUEST, RESPONSE, refresh=1)
        type = REQUEST.get_header('content-type', None)
        file = REQUEST['BODYFILE']
        data, size = self._read_data(file)
        if isinstance(data, str):
            data = data.encode('UTF-8')
        content_type = self._get_content_type(file, data, self.__name__,
                                              type or self.content_type)
        self.update_data(data, content_type, size)
        RESPONSE.setStatus(204)
        return RESPONSE
