def set_property_from_data(
    component_or_field: Union[UnicornView, UnicornField, Model], name: str, value: Any,
) -> None:
    """
    Sets properties on the component based on passed-in data.
    """
    try:
        if not hasattr(component_or_field, name):
            return
    except ValueError:
        return
