    if not isinstance(text, (str, unicodeT)):
        text = str(text)
    try:
        text = text.encode('utf8','replace')
    except ValueError:
        new_text = ''
        for c in text:
            try:
                new_text += c.encode('utf8')
            except:
                new_text += '?'
