        byte_s = _struct_2_long_long.pack(rand_longs[0] ^ urand_longs[0] ^ ctokens[0],
                                          rand_longs[1] ^ urand_longs[1] ^ ctokens[1])
    else:
        byte_s = _struct_2_long_long.pack(rand_longs[0] ^ ctokens[0],
                                          rand_longs[1] ^ ctokens[1])
    return str(uuid.UUID(bytes=byte_s, version=4))
    def select(self):
        if self.op == 'eq' and self.field == 'id' and self.value:
            key = self.keyprefix + ':' + str(self.value)
            if self.with_lock:
                acquire_lock(self.db.r_server, key + ':lock', self.value, 2)
            rtn = {to_native(k): v for k, v in self.db.r_server.hgetall(key).items()}
            if rtn:
                if self.unique_key:
                    if rtn['unique_key'] == to_bytes(self.unique_key):
                        rtn['update_record'] = self.update
                    else:
                        rtn = None
            return [Storage(self.db.convert_dict_string(rtn))] if rtn else []
        elif self.op in ('ge', 'gt') and self.field == 'id' and self.value == 0:
            rtn = []
            id_idx = "%s:id_idx" % self.keyprefix
            allkeys = self.db.r_server.smembers(id_idx)
            for sess in allkeys:
                val = self.db.r_server.hgetall(sess)
                if not val:
                    if self.session_expiry:
                        self.db.r_server.srem(id_idx, sess)
                    continue
                val = Storage(self.db.convert_dict_string(val))
                val.delete_record = RecordDeleter(
                    self.db, sess, self.keyprefix)
                rtn.append(val)
            return rtn
        else:
            raise Exception("Operation not supported")
def build_environment(request, response, session, store_current=True):
    """
    Build the environment dictionary into which web2py files are executed.
    """
    environment = dict(_base_environment_)
    if not request.env:
        request.env = Storage()
    response.models_to_run = [
        r'^\w+\.py$',
        r'^%s/\w+\.py$' % request.controller,
        r'^%s/%s/\w+\.py$' % (request.controller, request.function)
        ]
    T = environment['T'] = TranslatorFactory(pjoin(request.folder, 'languages'),
                                             request.env.http_accept_language)
    c = environment['cache'] = Cache(request)
    Validator.translator = staticmethod(lambda text: None if text is None else str(T(text)))
    if store_current:
        current.globalenv = environment
        current.request = request
        current.response = response
        current.session = session
        current.T = T
        current.cache = c
    if global_settings.is_jython:
        class mybuiltin(object):
            """
            NOTE could simple use a dict and populate it,
            NOTE not sure if this changes things though if monkey patching import.....
            """
            def __getitem__(self, key):
                try:
                    return getattr(builtin, key)
                except AttributeError:
                    raise KeyError(key)
            def __setitem__(self, key, value):
                setattr(self, key, value)
        global __builtins__
        __builtins__ = mybuiltin()
    environment['request'] = request
    environment['response'] = response
    environment['session'] = session
    environment['local_import'] = \
        lambda name, reload=False, app=request.application:\
        local_import_aux(name, reload, app)
    BaseAdapter.set_folder(pjoin(request.folder, 'databases'))
    custom_import_install()
    return environment
def check_credentials(request, other_application='admin',
                      expiration=60 * 60, gae_login=True):
    """Checks that user is authorized to access other_application"""
    if request.env.web2py_runtime_gae:
        from google.appengine.api import users
        if users.is_current_user_admin():
            return True
        elif gae_login:
            login_html = '<a href="%s">Sign in with your google account</a>.' \
                % users.create_login_url(request.env.path_info)
            raise HTTP(200, '<html><body>%s</body></html>' % login_html)
        else:
            return False
    else:
        t0 = time.time()
        dt = t0 - expiration
        s = get_session(request, other_application)
        r = (s.authorized and s.last_time and s.last_time > dt)
        if r:
            s.last_time = t0
            set_session(request, s, other_application)
        return r
def acquire_lock(conn, lockname, identifier, ltime=10):
    while True:
        if conn.set(lockname, identifier, ex=ltime, nx=True):
            return identifier
        time.sleep(.01)
